import assert from "node:assert/strict";
import { default as __ns1_approxEqual } from "./src/approx_equal.js";
import { default as __ns1_silhouette } from "./src/silhouette.js";
import { default as __ns1_silhouetteMetric } from "./src/silhouette_metric.js";
const ss = Object.freeze({ approxEqual: __ns1_approxEqual, silhouette: __ns1_silhouette, silhouetteMetric: __ns1_silhouetteMetric });
{
{
{
